const AUTO_GENERATED_PERSON_NAME_RE = /^Person\s+\d+$/i;

export function isAutoGeneratedPersonName(name: string | null | undefined): boolean {
  const trimmed = String(name ?? '').trim();
  return trimmed.length === 0 || AUTO_GENERATED_PERSON_NAME_RE.test(trimmed);
}

/**
 * Pick the best default display name when merging `sourceName` into `targetName`.
 * Keeps the target's name unless the target still has an auto-generated placeholder
 * ("Person 12" or empty) while the source already has a user-assigned name.
 */
export function resolveMergedPersonName(
  sourceName: string | null | undefined,
  targetName: string | null | undefined,
): string {
  const source = String(sourceName ?? '').trim();
  const target = String(targetName ?? '').trim();

  if (target && (!isAutoGeneratedPersonName(target) || isAutoGeneratedPersonName(source))) {
    return target;
  }
  if (source) {
    return source;
  }
  return target;
}

/**
 * Remap custom smart-album `person` rules that reference any merged source ID
 * so they continue matching the surviving `targetId`.
 * Returns `{ albums, changed }` without mutating the input array.
 */
export function remapSmartAlbumPersonIds<T extends Record<string, any>>(
  smartAlbums: T[] | null | undefined,
  sourceIds: number[],
  targetId: number,
): { albums: T[]; changed: boolean } {
  const list = Array.isArray(smartAlbums) ? smartAlbums : [];
  const sourceSet = new Set(
    sourceIds.map((id) => Number(id)).filter((id) => Number.isFinite(id) && id > 0 && id !== targetId),
  );
  if (sourceSet.size === 0 || !Number.isFinite(targetId) || targetId <= 0) {
    return { albums: list, changed: false };
  }

  let changed = false;
  const albums = list.map((album) => {
    const rules = album?.query?.rules;
    if (!Array.isArray(rules) || rules.length === 0) return album;

    let albumChanged = false;
    const nextRules = rules.map((rule: any) => {
      if (rule?.field !== 'person') return rule;
      const numericValue = Number(rule.value);
      if (rule.value !== null && rule.value !== '' && sourceSet.has(numericValue)) {
        albumChanged = true;
        return { ...rule, value: targetId };
      }
      return rule;
    });

    if (!albumChanged) return album;
    changed = true;
    return {
      ...album,
      query: {
        ...album.query,
        rules: nextRules,
      },
    };
  });

  return { albums: changed ? albums : list, changed };
}
